theorem commutative_cube_lemma
  {C : Type*} [CategoryTheory.Category C]
  {A₀₀ A₁₀ A₀₁ A₁₁ B₀₀ B₁₀ B₀₁ B₁₁ : C}
  {f₁ : A₀₀ ⟶ A₁₀} {f₂ : A₀₀ ⟶ A₀₁} {f₃ : A₁₀ ⟶ A₁₁} {f₄ : A₀₁ ⟶ A₁₁}
  {g₁ : B₀₀ ⟶ B₁₀} {g₂ : B₀₀ ⟶ B₀₁} {g₃ : B₁₀ ⟶ B₁₁} {g₄ : B₀₁ ⟶ B₁₁}
  {φ₁ : A₀₀ ⟶ B₀₀} {φ₂ : A₁₀ ⟶ B₁₀} {φ₃ : A₀₁ ⟶ B₀₁} {φ₄ : A₁₁ ⟶ B₁₁}
  (hfront : CategoryTheory.CommSq f₁ φ₁ φ₂ g₁)
  (hback : CategoryTheory.CommSq f₄ φ₃ φ₄ g₄)
  (hleft : CategoryTheory.CommSq f₂ φ₁ φ₃ g₂)
  (hright : CategoryTheory.CommSq f₃ φ₂ φ₄ g₃)
  (hbottom : CategoryTheory.CommSq f₁ f₂ f₃ f₄)
  (hepi : CategoryTheory.Epi φ₄)
  : CategoryTheory.CommSq g₁ g₂ g₃ g₄ := sorry
